pub type Pizza = { size: Str; cheese: Bool; pepperoni: Bool; }

pub type PizzaBuilder = { size: Str; cheese: Bool; pepperoni: Bool; }

impl PizzaBuilder {
  fn new() -> PizzaBuilder {
    return PizzaBuilder{ size: "medium", cheese: true, pepperoni: false };
  }
  fn size(self: &mut PizzaBuilder, s: Str) -> &mut PizzaBuilder { self.size = s; return self; }
  fn pepperoni(self: &mut PizzaBuilder, p: Bool) -> &mut PizzaBuilder { self.pepperoni = p; return self; }
  fn build(self: &PizzaBuilder) -> Pizza {
    return Pizza{ size: self.size, cheese: self.cheese, pepperoni: self.pepperoni };
  }
}

fn main() -> Int {
  let pizza = PizzaBuilder::new().size("large").pepperoni(true).build();
  var score = pizza.size.len() * 10;
  if pizza.pepperoni { score = score + 1; }
  return score;
}
